<?php
defined('ABSPATH') || exit;
/** Commercial-stage reconciliation never creates a sale or a receipt. */
final class GE_Work_History_Commercial {
    const STATE='_ge_commercial_followup_state';
    const AUDIT='_ge_commercial_history_audit';
    public static function source($key){$s=get_option('ge_work_reconciliation_v1',array());GE_Work_History_Storage::check();if(($s['organization_id']??'')!==GE_Organization::PRIMARY || empty($s['revisions']))throw new DomainException('No hay confirmaciones registradas.');$latest=end($s['revisions']);$matches=array();foreach($latest['rows'] as $r)if($r['key']===$key)$matches[]=$r;if(count($matches)!==1)throw new DomainException('Confirmación no única.');return array('revision'=>$latest['id'],'row'=>$matches[0],'fingerprints'=>$latest['source_fingerprints']);}
    public static function eligible($r){return ($r['quote_id'] && $r['commercial']==='partial' && $r['production']==='completed' && $r['payment']==='fully_paid') || in_array($r['commercial'],array('presented','consultation','discarded','confirmed'),true) && in_array($r['production'],array('not_performed','unconfirmed'),true) && ($r['order_id'] || $r['quote_id']);}
    public static function apply($key){
        if(!GE_Work_Historical_Reconciliation::allowed())throw new RuntimeException('Acceso denegado.');$s=self::source($key);$expected_source=$s;$r=$s['row'];if(!self::eligible($r))throw new DomainException('Esta confirmación requiere conciliar ejecución, no solo etapa comercial.');$id=(int)($r['order_id']?:$r['quote_id']);$kind=$r['order_id']?'order':'quote';$lock='ge_commercial_reconcile_'.($kind==='order'?'order_'.$id:$id);if(!GE_Work_Finance::lock($lock))throw new RuntimeException('El registro está siendo procesado.');$started=false;
        try{
            GE_Work_History_Storage::begin($kind==='order'?$id:0,$kind==='order'?array($id):array(),$kind==='quote'?array($id):array());$started=true;$s=self::source($key);$r=$s['row'];if($s!==$expected_source || !self::eligible($r) || (int)($r['order_id']?:$r['quote_id'])!==$id || ($r['order_id']?'order':'quote')!==$kind)throw new DomainException('Cambió la confirmación o la ficha vinculada; revisá antes de repetir.');$meta=$kind==='order'?GE_Work_Finance::strict_order($id):null;if($meta)$meta->read_meta_data(true);GE_Work_History_Storage::check();
            $audit=$meta?$meta->get_meta(self::AUDIT,true):get_post_meta($id,self::AUDIT,true);GE_Work_History_Storage::check();$audit=is_array($audit)?$audit:array();foreach($audit as $e)if(($e['source_revision']??'')===$s['revision'] && ($e['source_key']??'')===$key){GE_Work_History_Storage::commit();$started=false;return array('duplicate'=>true,'kind'=>$kind,'id'=>$id);}
            foreach(array('order_id','quote_id') as $field)if($r[$field]){$fp=$s['fingerprints'][$field.':'.$r[$field]]??'';if(!$fp || !hash_equals($fp,GE_Work_Historical_Reconciliation::source_fingerprint($field,(int)$r[$field])))throw new DomainException('El registro cambió; requiere revisar movimientos posteriores.');}
            $invoice_basis=$r['commercial']==='partial' && $r['production']==='completed';$target_state=$invoice_basis?'fulfilled_partial':$r['commercial'];$fields=array('_ge_work_payment_promise',self::STATE,'_ge_financial_reconciliation_basis','_ge_financial_line_allocation','_ge_quote_only','_ge_is_quote','_ge_production_operational_status','_ge_production_status',GE_WTP_Order_Lifecycle::STAGE_META,GE_WTP_Commercial_Quotes::STATUS_META);$before=array();foreach($fields as $field){$before[$field]=$meta?array('exists'=>$meta->meta_exists($field),'value'=>$meta->get_meta($field,true)):array('exists'=>metadata_exists('post',$id,$field),'value'=>get_post_meta($id,$field,true));GE_Work_History_Storage::check();}
            if($meta){$b=GE_Work_Finance::balance($meta);GE_Work_History_Storage::check();if(is_wp_error($b) || $b['amount_paid_cents'] || $meta->get_meta('_ge_delivery_confirmed_at',true) || $meta->get_meta(GE_WTP_Order_Lifecycle::DELIVERED_META,true))throw new DomainException('Hay cobros o entrega registrados; no se reemplazarán por un presupuesto.');$meta->update_meta_data(self::STATE,$r['commercial']);$meta->update_meta_data('_ge_quote_only','yes');$meta->update_meta_data('_ge_is_quote','yes');$meta->update_meta_data('_ge_production_operational_status',$r['commercial']==='discarded'?'closed':'active');$meta->update_meta_data('_ge_production_status','pending');$meta->update_meta_data(GE_WTP_Order_Lifecycle::STAGE_META,'recibido');}
            else{$q=GE_WTP_Commercial_Quotes::get($id,get_current_user_id());GE_Work_History_Storage::check();if(is_wp_error($q) || $q['converted_order_id'])throw new DomainException('Este presupuesto requiere revisar su pedido vinculado.');$state=$invoice_basis?$q['status']:array('presented'=>'sent','consultation'=>'draft','discarded'=>'cancelled','confirmed'=>'accepted')[$r['commercial']];update_post_meta($id,self::STATE,$target_state);if($invoice_basis){update_post_meta($id,'_ge_financial_reconciliation_basis','issued_invoices');GE_Work_History_Storage::check();update_post_meta($id,'_ge_financial_line_allocation','unconfirmed');GE_Work_History_Storage::check();}GE_Work_History_Storage::check();$hooks=array();if(class_exists('GE_CRM'))foreach(array('added_post_meta','updated_post_meta') as $hook){$priority=has_action($hook,array('GE_CRM','quote_meta'));if($priority!==false){$hooks[$hook]=$priority;remove_action($hook,array('GE_CRM','quote_meta'),$priority);}}try{update_post_meta($id,GE_WTP_Commercial_Quotes::STATUS_META,$state);GE_Work_History_Storage::check();}finally{foreach($hooks as $hook=>$priority)add_action($hook,array('GE_CRM','quote_meta'),$priority,4);}}
            $promise=GE_Work_Historical_Reconciliation::payment_promise($r);if($promise){if($meta)$meta->update_meta_data('_ge_work_payment_promise',$promise);else update_post_meta($id,'_ge_work_payment_promise',$promise);GE_Work_History_Storage::check();}
            $audit[]=array('id'=>wp_generate_uuid4(),'source_revision'=>$s['revision'],'source_key'=>$key,'before'=>$before,'state'=>$target_state,'actor'=>get_current_user_id(),'recorded_at'=>gmdate('c'),'actual_presentation_or_approval_date'=>null,'declarant'=>$r['declarant'],'note'=>$r['note']);if($meta){$meta->update_meta_data(self::AUDIT,$audit);GE_Work_History_Storage::save_order_meta($meta);}else update_post_meta($id,self::AUDIT,$audit);GE_Work_History_Storage::check();GE_Work_History_Storage::commit();$started=false;if($meta)GE_Work_Finance::clear_order_cache($id);else{clean_post_cache($id);if(class_exists('GE_CRM'))GE_CRM::quote_meta(0,$id,GE_WTP_Commercial_Quotes::STATUS_META,$state);}return array('saved'=>true,'kind'=>$kind,'id'=>$id,'state'=>$target_state);
        }catch(Throwable $e){if($started)GE_Work_History_Storage::abort();if($kind==='order')GE_Work_Finance::clear_order_cache($id);else clean_post_cache($id);throw $e;}finally{GE_Work_Finance::unlock($lock);}
    }
    public static function render($kind,$id){
        if(!GE_Work_Historical_Reconciliation::allowed())return;$s=get_option('ge_work_reconciliation_v1',array());if(empty($s['revisions']))return;$latest=end($s['revisions']);foreach($latest['rows'] as $r){if((int)$r[$kind.'_id']!==(int)$id || !self::eligible($r))continue;$object=$kind==='order'?wc_get_order($id):null;$audit=$object?$object->get_meta(self::AUDIT,true):get_post_meta($id,self::AUDIT,true);if(is_array($audit))foreach($audit as $event)if(($event['source_revision']??'')===$latest['id'] && ($event['source_key']??'')===$r['key']){echo '<p>Etapa comercial conciliada en esta ficha.</p>';GE_Work_Historical_Reconciliation::render_promise($object?$object->get_meta('_ge_work_payment_promise',true):get_post_meta($id,'_ge_work_payment_promise',true),$r['currency']);return;}echo '<form class="ge-admin-form" method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="ge_finance_work_history_commercial"><input type="hidden" name="source_key" value="'.esc_attr($r['key']).'">';wp_nonce_field('ge_finance_work_history_commercial_'.$r['key']);echo '<p>'.esc_html($r['note']).'</p><button class="ge-staff-button">Conciliar etapa comercial en esta ficha</button></form>';break;}
    }
    public static function handle(){if(!GE_Work_Historical_Reconciliation::allowed())GE_Work_Historical_Reconciliation::deny();$key=sanitize_key($_POST['source_key']??'');check_admin_referer('ge_finance_work_history_commercial_'.$key);try{$r=self::apply($key);}catch(Throwable $e){wp_die(esc_html($e->getMessage()),'',array('response'=>409));}wp_safe_redirect(add_query_arg(array('section'=>$r['kind']==='order'?'orders':'quotes',$r['kind'].'_id'=>$r['id']),home_url('/gestion/')));exit;}
}
add_action('admin_post_ge_finance_work_history_commercial',array('GE_Work_History_Commercial','handle'));
add_action('admin_post_nopriv_ge_finance_work_history_commercial',array('GE_Work_Historical_Reconciliation','deny'));
